void WolphunLang::SetLanguage(TInt aIndex)
{
    if (aIndex < 0 || aIndex >= EWolphunLangCount) aIndex = 0;
    WolphunWsd::SetLang(aIndex);
}

TInt WolphunLang::Language(){ return WolphunWsd::Lang(); }

TPtrC WolphunLang::T(TInt aKey)
{
    if (aKey < 0 || aKey >= EWolphunStrCount) return TPtrC();
    return TPtrC(KStrings[aKey][WolphunWsd::Lang()]);
}

TPtrC WolphunLang::LanguageName(TInt aIndex)
{
    if (aIndex < 0 || aIndex >= EWolphunLangCount) aIndex = 0;
    return TPtrC(KLangNames[aIndex]);
}
